@import "tailwindcss";
@import "tw-animate-css";

/*
 * EzyFusion design tokens (DESIGN_SYSTEM.md §2). Variables live in :root and are
 * registered under --color-* below; an unregistered token generates no utility.
 * Dark mode is deferred, so there is no .dark block and no dark variant.
 */
:root {
  --background: #f5f7fb;
  --foreground: #0f172a;
  --card: #ffffff;
  --card-foreground: #0f172a;
  --popover: #ffffff;
  --popover-foreground: #0f172a;
  --primary: #1e40af;
  --primary-foreground: #ffffff;
  --secondary: #eef2f8;
  --secondary-foreground: #0f172a;
  --muted: #eef2f8;
  --muted-foreground: #64748b; /* white surfaces only */
  --accent: #eef2f8;
  --accent-foreground: #0f172a;
  --destructive: #dc2626;
  --destructive-foreground: #ffffff;
  --border: #e2e8f0; /* decorative dividers */
  --input: #7c8ba1; /* control boundary, >= 3:1 */
  --ring: #1e40af;
  --radius: 0.5rem;

  /* extension tokens (11) */
  --success: #16a34a;
  --success-subtle: #dcfce7;
  --success-subtle-foreground: #166534;
  --warning: #d97706;
  --warning-subtle: #fef3c7;
  --warning-subtle-foreground: #92400e;
  --destructive-subtle: #fee2e2;
  --destructive-subtle-foreground: #991b1b;
  --info-subtle: #dbeafe;
  --info-subtle-foreground: #1e40af;
  --muted-foreground-strong: #526077; /* muted text on page background / tinted fills */
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  --color-success: var(--success);
  --color-success-subtle: var(--success-subtle);
  --color-success-subtle-foreground: var(--success-subtle-foreground);
  --color-warning: var(--warning);
  --color-warning-subtle: var(--warning-subtle);
  --color-warning-subtle-foreground: var(--warning-subtle-foreground);
  --color-destructive-subtle: var(--destructive-subtle);
  --color-destructive-subtle-foreground: var(--destructive-subtle-foreground);
  --color-info-subtle: var(--info-subtle);
  --color-info-subtle-foreground: var(--info-subtle-foreground);
  --color-muted-foreground-strong: var(--muted-foreground-strong);

  --radius-sm: calc(var(--radius) - 2px);
  --radius-md: var(--radius);
  --radius-lg: calc(var(--radius) + 2px);
  --radius-xl: calc(var(--radius) + 6px);
  --radius-4xl: 9999px;

  --font-sans: var(--font-geist-sans);
  --font-heading: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

@layer base {
  * {
    border-color: var(--border); /* Tailwind v4 defaults to currentColor */
  }
  html {
    @apply font-sans antialiased;
  }
  body {
    @apply bg-background text-foreground;
  }
  /* Fixed headers must not hide focused elements (WCAG 2.4.11) */
  :target,
  :focus-visible {
    scroll-margin-top: 4.5rem;
  }
}

