/**
 * Money arithmetic. Amounts are integers in a currency's minor unit, held as bigint.
 * No formatting here and no floating point: formatting lives in lib/format.ts.
 * API-specific parsing and rounding rules are deferred until requirements are known.
 */
export type MinorUnits = bigint;

export function sumMinor(values: readonly MinorUnits[]): MinorUnits {
  return values.reduce((total, value) => total + value, BigInt(0));
}

/**
 * Strict decimal-string to minor-unit conversion for the demo form.
 * Accepts only digits with an optional fraction of at most `fractionDigits`
 * places; anything else returns null. Never rounds.
 */
export function parseDecimalToMinor(
  input: string,
  fractionDigits: number,
): MinorUnits | null {
  const match = /^(\d+)(?:\.(\d+))?$/.exec(input.trim());
  if (!match) return null;
  const whole = match[1];
  const fraction = match[2] ?? "";
  if (fraction.length > fractionDigits) return null;
  return BigInt(whole + fraction.padEnd(fractionDigits, "0"));
}

/**
 * Presentation only: turns already-computed values into display strings with Intl.
 * No totals or arithmetic on money here (see lib/money.ts).
 */
import type { MinorUnits } from "@/lib/money";

/** Demo-only placeholders; real currency and locale come from the requirements. */
export const DEMO_CURRENCY = "USD";
export const DEMO_LOCALE = "en-US";

/** Minor-unit digits for a currency, as the runtime's Intl data defines them (JPY 0, USD 2, KWD 3). */
export function getFractionDigits(currency: string, locale: string): number {
  return (
    new Intl.NumberFormat(locale, { style: "currency", currency }).resolvedOptions()
      .maximumFractionDigits ?? 2
  );
}

/** Inserts the decimal point by string manipulation, so no float division is involved. */
export function minorToDecimalString(
  minor: MinorUnits,
  fractionDigits: number,
): string {
  const negative = minor < BigInt(0);
  const digits = (negative ? -minor : minor).toString();
  let result = digits;
  if (fractionDigits > 0) {
    const padded = digits.padStart(fractionDigits + 1, "0");
    result = `${padded.slice(0, -fractionDigits)}.${padded.slice(-fractionDigits)}`;
  }
  return negative ? `-${result}` : result;
}

export type FormatMoneyOptions = {
  currency: string;
  locale?: string;
  signDisplay?: Intl.NumberFormatOptions["signDisplay"];
};

export function formatMinorUnits(
  minor: MinorUnits,
  { currency, locale = DEMO_LOCALE, signDisplay }: FormatMoneyOptions,
): string {
  const digits = getFractionDigits(currency, locale);
  const formatter = new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    signDisplay,
  });
  // Intl.NumberFormat v3 formats numeric strings as exact decimals.
  return formatter.format(minorToDecimalString(minor, digits) as `${number}`);
}

/** `isoDate` is a calendar date (YYYY-MM-DD); rendered in UTC so it never shifts a day. */
export function formatDate(isoDate: string, locale: string = DEMO_LOCALE): string {
  return new Intl.DateTimeFormat(locale, {
    dateStyle: "medium",
    timeZone: "UTC",
  }).format(new Date(`${isoDate}T00:00:00Z`));
}

