            </Button>
          }
        />
      ) : (
        <Table>
          <TableCaption className="sr-only">
            Invoices, page {currentPage} of {pageCount}
          </TableCaption>
          <TableHeader>
            <TableRow className="hover:bg-transparent">
              <TableHead scope="col" className="h-11 px-4 text-xs text-muted-foreground-strong">
                Invoice
              </TableHead>
              <TableHead scope="col" className="h-11 px-4 text-xs text-muted-foreground-strong">
                Due date
              </TableHead>
              <TableHead scope="col" className="h-11 px-4 text-xs text-muted-foreground-strong">
                Status
              </TableHead>
              <TableHead scope="col" className="h-11 px-4 text-right text-xs text-muted-foreground-strong">
                Amount
              </TableHead>
              <TableHead scope="col" className="h-11 w-14 px-4">
                <span className="sr-only">Actions</span>
              </TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {rows.map((invoice) => {
              const { label, tone } = statusMeta[invoice.status];
              return (
                <TableRow key={invoice.id} className="h-14">
                  <TableCell className="px-4">
                    <div className="font-medium">{invoice.customer}</div>
                    <div className="font-mono text-xs text-muted-foreground-strong">
                      {invoice.id} · {invoice.terms}
                    </div>
                  </TableCell>
                  <TableCell className="px-4">
                    <time dateTime={invoice.dueDate}>{formatDate(invoice.dueDate)}</time>
                  </TableCell>
                  <TableCell className="px-4">
                    <StatusBadge tone={tone}>{label}</StatusBadge>
                  </TableCell>
                  <TableCell className="px-4 text-right">
                    <MoneyDisplay amount={invoice.amount} currency={DEMO_CURRENCY} />
                  </TableCell>
                  <TableCell className="px-4">
                    <DropdownMenu>
                      <DropdownMenuTrigger
                        render={<Button variant="ghost" size="icon" />}
                      >
                        <MoreHorizontalIcon aria-hidden="true" />
                        <span className="sr-only">Actions for {invoice.id}</span>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem
                          onClick={() => void navigator.clipboard?.writeText(invoice.id)}
                        >
                          Copy reference
                        </DropdownMenuItem>
                        <DropdownMenuItem disabled>View details (demo)</DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              );
            })}
          </TableBody>
        </Table>
      )}

      {rows.length > 0 ? (
        <div className="flex flex-col items-center gap-3 border-t p-4 sm:flex-row sm:justify-between">
          <p className="text-sm text-muted-foreground" aria-live="polite">
            {start + 1}–{start + rows.length} of {filtered.length}
          </p>
