                    event.preventDefault();
                    goTo(currentPage - 1);
                  }}
                />
              </PaginationItem>
              <PaginationItem className="sm:hidden">
                <span className="px-2 text-sm text-muted-foreground">
                  Page {currentPage} of {pageCount}
                </span>
              </PaginationItem>
              {pages.map((number) => (
                <PaginationItem key={number} className="hidden sm:block">
