"use client";

import { useId, useState, type FormEvent, type ReactNode } from "react";
import { CircleAlertIcon } from "lucide-react";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { MoneyDisplay } from "@/components/money-display";
import { DEMO_CURRENCY, DEMO_LOCALE, getFractionDigits } from "@/lib/format";
import { parseDecimalToMinor } from "@/lib/money";

const termsItems = [
  { value: "net-15", label: "Net 15" },
  { value: "net-30", label: "Net 30" },
  { value: "net-45", label: "Net 45" },
];

type Values = { customer: string; amount: string; dueDate: string; terms: string };
type Errors = Partial<Record<keyof Values, string>>;

const fractionDigits = getFractionDigits(DEMO_CURRENCY, DEMO_LOCALE);
const fieldOrder: (keyof Values)[] = ["customer", "amount", "dueDate", "terms"];

function validate(values: Values): Errors {
  const errors: Errors = {};
  if (values.customer.trim() === "") errors.customer = "Enter a customer name.";
  if (values.amount.trim() === "") {
    errors.amount = "Enter an amount.";
  } else if (parseDecimalToMinor(values.amount, fractionDigits) === null) {
    errors.amount = `Use digits with at most ${fractionDigits} decimal places, for example 1250.00.`;
  }
  if (values.dueDate === "") errors.dueDate = "Choose a due date.";
  if (values.terms === "") errors.terms = "Choose payment terms.";
  return errors;
}

type FieldProps = {
  id: string;
  label: string;
  helper?: string;
  error?: string;
  children: ReactNode;
};

/** Page-local label + control + helper + error wiring (no shared field wrapper in the v0.2 inventory). */
function Field({ id, label, helper, error, children }: FieldProps) {
  return (
    <div className="space-y-1.5">
      <label htmlFor={id} className="text-sm font-medium">
        {label} <span aria-hidden="true">*</span>
        <span className="sr-only">(required)</span>
      </label>
      {children}
      {helper ? (
        <p id={`${id}-helper`} className="text-xs text-muted-foreground">
          {helper}
        </p>
      ) : null}
      {error ? (
        <p id={`${id}-error`} className="flex items-start gap-1.5 text-sm text-destructive">
          <CircleAlertIcon aria-hidden="true" className="mt-0.5 size-4 shrink-0" />
          {error}
        </p>
      ) : null}
    </div>
  );
}

export function NewInvoiceForm() {
  const uid = useId();
  const ids = {
    customer: `${uid}-customer`,
    amount: `${uid}-amount`,
    dueDate: `${uid}-due`,
    terms: `${uid}-terms`,
  };

  const [values, setValues] = useState<Values>({
    customer: "",
    amount: "",
    dueDate: "",
    terms: "net-30",
  });
  const [submitted, setSubmitted] = useState(false);
  const [saved, setSaved] = useState<bigint | null>(null);

  // After the first submit, errors track the inputs live and the summary disappears only once all are fixed.
  const errors = submitted ? validate(values) : {};
  const errorFields = fieldOrder.filter((key) => errors[key]);

  function update(key: keyof Values, value: string) {
    setValues((current) => ({ ...current, [key]: value }));
    setSaved(null);
  }

  function describedBy(key: keyof Values, hasHelper: boolean) {
    const parts = [hasHelper ? `${ids[key]}-helper` : null, errors[key] ? `${ids[key]}-error` : null];
    return parts.filter(Boolean).join(" ") || undefined;
  }

  function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitted(true);
    const result = validate(values);
    const first = fieldOrder.find((key) => result[key]);
    if (first) {
      document.getElementById(ids[first])?.focus();
      return;
    }
    // Demo only: nothing is stored or sent.
    setSaved(parseDecimalToMinor(values.amount, fractionDigits));
  }

  return (
    <Card className="gap-0 p-0" id="new-invoice">
      <div className="border-b p-4">
        <h2 className="text-lg font-semibold">New invoice (demo form)</h2>
        <p className="text-sm text-muted-foreground">
          Validates in the browser only. Nothing is saved or sent.
        </p>
      </div>

      <form noValidate onSubmit={onSubmit} className="max-w-2xl space-y-4 p-4 md:p-6">
        {errorFields.length > 0 ? (
          <Alert variant="destructive">
            <CircleAlertIcon aria-hidden="true" />
            <AlertTitle>
              {errorFields.length === 1 ? "1 field needs attention" : `${errorFields.length} fields need attention`}
            </AlertTitle>
            <AlertDescription>
              <ul className="list-disc pl-4">
                {errorFields.map((key) => (
                  <li key={key}>
                    <a href={`#${ids[key]}`} className="underline underline-offset-2">
                      {errors[key]}
                    </a>
                  </li>
                ))}
              </ul>
            </AlertDescription>
          </Alert>
        ) : null}

        {saved !== null ? (
          <Alert variant="success">
            <AlertTitle>Demo invoice accepted</AlertTitle>
            <AlertDescription>
              Parsed amount: <MoneyDisplay amount={saved} currency={DEMO_CURRENCY} />. Nothing was saved.
            </AlertDescription>
          </Alert>
        ) : null}

        <Field id={ids.customer} label="Customer name" error={errors.customer}>
          <Input
            id={ids.customer}
            value={values.customer}
            maxLength={80}
            autoComplete="off"
            aria-required="true"
            aria-invalid={errors.customer ? true : undefined}
            aria-describedby={describedBy("customer", false)}
            onChange={(event) => update("customer", event.target.value)}
          />
        </Field>

        <div className="grid gap-4 md:grid-cols-2">
          <Field
            id={ids.amount}
            label={`Amount (${DEMO_CURRENCY})`}
            helper={`Up to ${fractionDigits} decimal places.`}
            error={errors.amount}
          >
            <Input
              id={ids.amount}
              inputMode="decimal"
              autoComplete="off"
              className="text-right tabular-nums"
              value={values.amount}
              aria-required="true"
              aria-invalid={errors.amount ? true : undefined}
              aria-describedby={describedBy("amount", true)}
              onChange={(event) => update("amount", event.target.value)}
            />
          </Field>

          <Field id={ids.dueDate} label="Due date" error={errors.dueDate}>
            <Input
              id={ids.dueDate}
              type="date"
              value={values.dueDate}
              aria-required="true"
              aria-invalid={errors.dueDate ? true : undefined}
              aria-describedby={describedBy("dueDate", false)}
              onChange={(event) => update("dueDate", event.target.value)}
            />
          </Field>
        </div>

        <Field id={ids.terms} label="Payment terms" error={errors.terms}>
          <Select
            items={termsItems}
            value={values.terms}
            onValueChange={(value) => update("terms", value ?? "")}
          >
            <SelectTrigger
              id={ids.terms}
              className="w-full md:w-60"
              aria-required="true"
              aria-invalid={errors.terms ? true : undefined}
              aria-describedby={describedBy("terms", false)}
            >
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {termsItems.map((item) => (
                <SelectItem key={item.value} value={item.value}>
                  {item.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Field>

        <div className="flex flex-col-reverse gap-2 pt-2 sm:flex-row sm:justify-end">
          <Button
            type="reset"
            variant="outline"
            onClick={() => {
              setValues({ customer: "", amount: "", dueDate: "", terms: "net-30" });
              setSubmitted(false);
              setSaved(null);
            }}
          >
            Clear form
          </Button>
          <Button type="submit">Create invoice</Button>
        </div>
      </form>
    </Card>
  );
}

