import Link from "next/link";
import { PlusIcon } from "lucide-react";
import { buttonVariants } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { MoneyDisplay } from "@/components/money-display";
import { PageHeader } from "@/components/page-header";
import { DEMO_CURRENCY } from "@/lib/format";
import { sumMinor } from "@/lib/money";
import { demoInvoices, type InvoiceStatus } from "./_components/demo-data";
import { InvoicesTable } from "./_components/invoices-table";
import { NewInvoiceForm } from "./_components/new-invoice-form";
import { StatesDemo } from "./_components/states-demo";

/** Totals are computed with bigint arithmetic (lib/money); MoneyDisplay only formats the result. */
function totalFor(statuses: InvoiceStatus[]) {
  const matching = demoInvoices.filter((invoice) => statuses.includes(invoice.status));
  return { count: matching.length, total: sumMinor(matching.map((invoice) => invoice.amount)) };
}

const summaries = [
  { label: "Total invoiced", ...totalFor(["paid", "pending", "overdue", "processing"]) },
  { label: "Collected", ...totalFor(["paid"]) },
  { label: "Outstanding", ...totalFor(["pending", "processing", "overdue"]) },
  { label: "Overdue", ...totalFor(["overdue"]) },
];

export default function DashboardPage() {
  return (
    <>
      <PageHeader
        title="Dashboard"
        description="Design-system validation page with fictional data."
        actions={
          <Link href="#new-invoice" className={buttonVariants()}>
            <PlusIcon aria-hidden="true" data-icon="inline-start" />
            Create invoice
          </Link>
        }
      />

      <section aria-labelledby="summary-heading">
        <h2 id="summary-heading" className="sr-only">
          Financial summary
        </h2>
        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
          {summaries.map(({ label, count, total }) => (
            <Card key={label} className="gap-1 p-4 md:p-6">
              <p className="text-sm font-medium text-muted-foreground">{label}</p>
              <p className="text-2xl font-semibold tracking-tight">
                <MoneyDisplay amount={total} currency={DEMO_CURRENCY} className="font-semibold" />
              </p>
              <p className="text-xs text-muted-foreground">
                {count} {count === 1 ? "invoice" : "invoices"}
              </p>
            </Card>
          ))}
        </div>
      </section>

      <InvoicesTable />
      <NewInvoiceForm />
      <StatesDemo />
    </>
  );
}

