import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { parseDecimalToMinor, sumMinor } from "./money.ts";

describe("sumMinor", () => {
  it("sums integer minor units exactly (no 0.1 + 0.2 drift)", () => {
    assert.equal(sumMinor([BigInt(10), BigInt(20)]), BigInt(30));
  });

  it("returns zero for an empty list", () => {
    assert.equal(sumMinor([]), BigInt(0));
  });

  it("handles negative amounts", () => {
    assert.equal(sumMinor([BigInt(10000), BigInt(-4500)]), BigInt(5500));
  });

  it("stays exact beyond Number.MAX_SAFE_INTEGER", () => {
    const beyondSafe = BigInt("9007199254740993"); // MAX_SAFE_INTEGER + 2
    assert.equal(sumMinor([beyondSafe, BigInt(1)]), BigInt("9007199254740994"));
    assert.notEqual(Number(beyondSafe), Number(beyondSafe) + 1 - 1 + 0 === 0 ? 0 : -1); // number cannot represent it exactly
    assert.equal(BigInt(Number(beyondSafe)) === beyondSafe, false);
  });
});

describe("parseDecimalToMinor", () => {
  it("parses by currency precision: USD 2, JPY 0, KWD 3", () => {
    assert.equal(parseDecimalToMinor("1250.5", 2), BigInt(125050));
    assert.equal(parseDecimalToMinor("1250", 2), BigInt(125000));
    assert.equal(parseDecimalToMinor("0.05", 2), BigInt(5));
    assert.equal(parseDecimalToMinor("1250", 0), BigInt(1250));
    assert.equal(parseDecimalToMinor("1.234", 3), BigInt(1234));
  });

  it("trims surrounding whitespace", () => {
    assert.equal(parseDecimalToMinor("  12.50 ", 2), BigInt(1250));
  });

  it("parses large amounts without precision loss", () => {
    assert.equal(parseDecimalToMinor("90071992547409.93", 2), BigInt("9007199254740993"));
  });

  it("rejects more decimals than the currency allows instead of rounding", () => {
    assert.equal(parseDecimalToMinor("12.345", 2), null);
    assert.equal(parseDecimalToMinor("12.5", 0), null);
    assert.equal(parseDecimalToMinor("1.2345", 3), null);
  });

  it("rejects malformed input", () => {
    for (const input of [
      "",
      "   ",
      "abc",
      "1,250.00",
      "-5",
      "+5",
      ".5",
      "5.",
      "1e3",
      "1.2.3",
      "12 34",
      "$12",
      "१२", // non-ASCII digits
      "NaN",
      "Infinity",
    ]) {
      assert.equal(parseDecimalToMinor(input, 2), null, `expected null for ${JSON.stringify(input)}`);
    }
  });
});

