cat > src/rls.ts <<'EOF'
import type { Prisma } from "./db.ts";

type Claims = { sub: string; role: "authenticated" } | { sub?: undefined; role: "anon" };

/**
 * Runs `fn` inside a transaction that behaves like a Supabase API request:
 * the session role is switched to `authenticated` / `anon` (both subject to RLS)
 * and the JWT claims are set so `auth.uid()` resolves. SET LOCAL ends with the transaction,
 * so a pooled connection cannot leak the role or the user to the next request.
 *
 * `claims.sub` MUST come from a server-verified token, never from request input.
 */
export async function withRls<T>(
  prisma: Prisma,
  claims: Claims,
  fn: (tx: Parameters<Parameters<Prisma["$transaction"]>[0]>[0]) => Promise<T>,
): Promise<T> {
  return prisma.$transaction(async (tx) => {
    await tx.$executeRaw`select set_config('request.jwt.claims', ${JSON.stringify(claims)}, true)`;
    // Role names cannot be bind parameters; the union type above restricts them to two literals.
    await tx.$executeRawUnsafe(`set local role ${claims.role}`);
    return fn(tx);
  });
}
EOF
