cat > prisma/seed.ts <<'EOF'
import { createClient } from "@supabase/supabase-js";
import { createPrisma } from "../src/db.ts";
import { NOTES, USER_A, USER_B } from "../src/seed-data.ts";

try {
  process.loadEnvFile();
} catch {
  /* rely on process env */
}

const url = process.env.SUPABASE_URL;
const serviceKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
if (!url || !serviceKey) throw new Error("SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are required (server-side seed only)");

const admin = createClient(url, serviceKey, { auth: { persistSession: false, autoRefreshToken: false } });
const prisma = createPrisma();

// Idempotent and deterministic: fixed ids, emails, timestamps; existing rows are replaced.
for (const user of [USER_A, USER_B]) {
  const existing = await admin.auth.admin.getUserById(user.id);
  if (existing.data.user) {
    const { error } = await admin.auth.admin.deleteUser(user.id);
    if (error) throw error;
  }
  const { data, error } = await admin.auth.admin.createUser({
    id: user.id,
    email: user.email,
    password: user.password,
    email_confirm: true,
  });
  if (error) throw error;
  if (data.user.id !== user.id) throw new Error(`Auth did not honour the requested id for ${user.email}`);
}

await prisma.$transaction([
  prisma.sandboxNote.deleteMany(),
  prisma.sandboxNote.createMany({ data: NOTES.map((n) => ({ ...n })) }),
]);

console.log(`seeded users=2 notes=${await prisma.sandboxNote.count()}`);
