/**
 * `prisma migrate dev` replays all migrations on a scratch (shadow) database. Our RLS migration refers to
 * Supabase's `auth` schema, which a fresh database does not have, so we keep one persistent shadow database
 * with minimal stand-ins for `auth.users` and `auth.uid()`. Roles (anon, authenticated, ...) are cluster-wide
 * and already exist. Run once after `supabase start` / `supabase db reset`. Idempotent. Local only.
 */
import pg from "pg";

try {
  process.loadEnvFile();
} catch {
  /* rely on process env */
}

const admin = new pg.Client({ connectionString: process.env.DATABASE_URL });
await admin.connect();
const exists = await admin.query("select 1 from pg_database where datname = 'ezy_shadow'");
if (exists.rowCount === 0) await admin.query("create database ezy_shadow");
await admin.end();

const shadow = new pg.Client({ connectionString: process.env.SHADOW_DATABASE_URL });
await shadow.connect();
await shadow.query(`
  create schema if not exists auth;
  create table if not exists auth.users (id uuid primary key);
  create or replace function auth.uid() returns uuid language sql stable as $$
    select coalesce(
      nullif(current_setting('request.jwt.claim.sub', true), ''),
      (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')
    )::uuid
  $$;
  grant usage on schema auth to anon, authenticated, service_role;
`);
await shadow.end();
console.log("shadow database ready: ezy_shadow");
EOF
