-- Ownership link to Supabase Auth: deleting a user removes their rows.
ALTER TABLE "sandbox_notes"
  ADD CONSTRAINT "sandbox_notes_owner_id_fkey"
  FOREIGN KEY ("owner_id") REFERENCES auth.users(id) ON DELETE CASCADE;

-- Row Level Security -------------------------------------------------------
ALTER TABLE "sandbox_notes" ENABLE ROW LEVEL SECURITY;

-- Defence in depth: the anonymous role gets no table privileges at all.
REVOKE ALL ON "sandbox_notes" FROM anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON "sandbox_notes" TO authenticated;
GRANT ALL ON "sandbox_notes" TO service_role;

-- (select auth.uid()) is evaluated once per statement instead of once per row.
CREATE POLICY "sandbox_notes_select_own" ON "sandbox_notes"
  FOR SELECT TO authenticated USING (owner_id = (select auth.uid()));
CREATE POLICY "sandbox_notes_insert_own" ON "sandbox_notes"
  FOR INSERT TO authenticated WITH CHECK (owner_id = (select auth.uid()));
CREATE POLICY "sandbox_notes_update_own" ON "sandbox_notes"
  FOR UPDATE TO authenticated
  USING (owner_id = (select auth.uid()))
  WITH CHECK (owner_id = (select auth.uid()));
CREATE POLICY "sandbox_notes_delete_own" ON "sandbox_notes"
  FOR DELETE TO authenticated USING (owner_id = (select auth.uid()));
EOF
