/**
 * Disposable RLS / authorization experiment against local Supabase. Every line printed is the result of a real
 * query or request made by this script. Exits non-zero if any expectation fails.
 * Requires a seeded database (npm run db:reset).
 */
import { createClient, type SupabaseClient } from "@supabase/supabase-js";
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";
import { createPrisma } from "../src/db.ts";
import { withRls } from "../src/rls.ts";
import { NOTES, USER_A, USER_B } from "../src/seed-data.ts";

try {
  process.loadEnvFile();
} catch {
  /* rely on process env */
}

const { SUPABASE_URL: url, SUPABASE_ANON_KEY: anonKey, SUPABASE_SERVICE_ROLE_KEY: serviceKey, DATABASE_URL: dbUrl } = process.env;
if (!url || !anonKey || !serviceKey || !dbUrl) throw new Error("env incomplete; see .env.example");

type Row = { id: string; check: string; expected: string; actual: string; ok: boolean };
const results: Row[] = [];
const record = (id: string, check: string, expected: string, actual: string, ok: boolean) => {
  results.push({ id, check, expected, actual, ok });
};
const noSession = { auth: { persistSession: false, autoRefreshToken: false } };
const idsOf = (rows: { id: string }[] | null) => (rows ?? []).map((r) => r.id).sort();
const A_IDS = NOTES.filter((n) => n.ownerId === USER_A.id).map((n) => n.id).sort();
const B_IDS = NOTES.filter((n) => n.ownerId === USER_B.id).map((n) => n.id).sort();
const same = (a: string[], b: string[]) => JSON.stringify(a) === JSON.stringify(b);

const anon = createClient(url, anonKey, noSession);
const admin = createClient(url, serviceKey, noSession);
const prisma = createPrisma();

async function login(user: { email: string; password: string }) {
  const c = createClient(url!, anonKey!, noSession);
  const { data, error } = await c.auth.signInWithPassword(user);
  if (error || !data.session) throw error ?? new Error("no session");
  const token = data.session.access_token;
  const api = createClient(url!, anonKey!, { ...noSession, global: { headers: { Authorization: `Bearer ${token}` } } });
  return { token, api };
}
const A = await login(USER_A);
const B = await login(USER_B);

// ---- 1. Unauthenticated access ------------------------------------------------------------------------------
{
  const r = await anon.from("sandbox_notes").select("id");
  record("U1", "anon API select", "denied or empty", r.error ? `error ${r.error.code}: ${r.error.message}` : `${r.data?.length} rows`, !!r.error || (r.data?.length ?? 0) === 0);
  const w = await anon.from("sandbox_notes").insert({ owner_id: USER_A.id, title: "anon write" });
  record("U2", "anon API insert", "denied", w.error ? `error ${w.error.code}: ${w.error.message}` : "accepted", !!w.error);
  const p = await withRls(prisma, { role: "anon" }, (tx) => tx.sandboxNote.findMany()).then(
    (rows) => `${rows.length} rows`,
    (e: Error) => `error: ${e.message.split("\n").pop()}`,
  );
  record("U3", "Prisma as anon role", "denied or empty", p, p.startsWith("error") || p === "0 rows");
}

// ---- 2. User isolation through the Supabase API (PostgREST enforces RLS as role `authenticated`) -------------------
async function isolation(label: string, me: typeof A, mine: string[], theirs: string[], theirOwner: string) {
