import "server-only";
import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";
import type { NextRequest } from "next/server";
import type { NextResponse } from "next/server";

const url = () => process.env.NEXT_PUBLIC_SUPABASE_URL!;
const anonKey = () => process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;

/**
 * For Server Components. Cookie writes are ignored here because Server Components cannot set cookies;
 * src/proxy.ts refreshes the session before rendering.
 */
export async function createServerComponentClient() {
  const store = await cookies();
  return createServerClient(url(), anonKey(), {
    cookies: {
      getAll: () => store.getAll(),
      setAll: (list) => {
        try {
          list.forEach(({ name, value, options }) => store.set(name, value, options));
        } catch {
          /* called from a Server Component: safe to ignore */
        }
      },
    },
  });
}

type CookieWrite = { name: string; value: string; options: Parameters<NextResponse["cookies"]["set"]>[2] };

/**
 * For Route Handlers. Reads cookies from the request and collects the cookie writes (plus the
 * no-store cache headers the library requires) so they can be applied to whichever response is returned.
 */
export function createRouteClient(request: NextRequest) {
  const writes: CookieWrite[] = [];
  const extraHeaders: Record<string, string> = {};
  const supabase = createServerClient(url(), anonKey(), {
    cookies: {
      getAll: () => request.cookies.getAll(),
      setAll: (list, headers) => {
        list.forEach(({ name, value, options }) => writes.push({ name, value, options }));
        Object.assign(extraHeaders, headers);
      },
    },
  });
  const applyTo = <T extends NextResponse>(response: T): T => {
    writes.forEach(({ name, value, options }) => response.cookies.set(name, value, options));
    Object.entries(extraHeaders).forEach(([k, v]) => response.headers.set(k, v));
    return response;
  };
  return { supabase, applyTo };
}
