import "server-only";
import { redirect } from "next/navigation";
import { createServerComponentClient } from "@/lib/supabase/server";

declare const verified: unique symbol;
/**
 * An identity that Supabase Auth has verified for THIS request. It can only be produced by
 * verifyUser(); data-layer functions require it, so a user id taken from request input
 * (query, body, header) cannot be passed where an AuthedUser is expected.
 */
export type AuthedUser = { readonly id: string; readonly email: string | undefined; readonly [verified]: true };

export function authedUser(id: string, email: string | undefined): AuthedUser {
  return { id, email } as AuthedUser;
}

/**
 * getUser() asks the Auth server to validate the access token (signature, expiry AND that the session
 * still exists), so revoked sessions are rejected. getSession() only decodes the cookie and must not be
 * used for authorization.
 */
export async function verifyUser(): Promise<AuthedUser | null> {
  const supabase = await createServerComponentClient();
  const { data, error } = await supabase.auth.getUser();
  if (error || !data.user) return null;
  return authedUser(data.user.id, data.user.email);
}

export async function requireUser(): Promise<AuthedUser> {
  const user = await verifyUser();
  if (!user) redirect("/login");
  return user;
}
