import "server-only";
import { PrismaPg } from "@prisma/adapter-pg";
import { PrismaClient } from "@/generated/prisma/client";
import type { AuthedUser } from "./auth";

const globalForPrisma = globalThis as unknown as { prisma?: PrismaClient };

// DATABASE_URL carries database credentials and is only ever read on the server.
// The client is NOT exported: every query must go through withUser(), i.e. through RLS.
const prisma =
  globalForPrisma.prisma ?? new PrismaClient({ adapter: new PrismaPg({ connectionString: process.env.DATABASE_URL }) });
if (process.env.NODE_ENV !== "production") globalForPrisma.prisma = prisma;

type Tx = Parameters<Parameters<typeof prisma.$transaction>[0]>[0];

/**
 * Runs `fn` as the verified user. The connection role (postgres) bypasses RLS, so each transaction first
 * switches to the RLS-bound `authenticated` role and sets the JWT claims that auth.uid() reads.
 * SET LOCAL lasts only for this transaction, so pooled connections cannot leak identity.
 */
export function withUser<T>(user: AuthedUser, fn: (tx: Tx) => Promise<T>): Promise<T> {
  return prisma.$transaction(async (tx) => {
    await tx.$executeRaw`select set_config('request.jwt.claims', ${JSON.stringify({ sub: user.id, role: "authenticated" })}, true)`;
    await tx.$executeRawUnsafe("set local role authenticated");
    return fn(tx);
  });
}
EOF
