import "server-only";
import type { AuthedUser } from "./auth";
import { withUser } from "./db";

// Every function takes an AuthedUser. Authorization = explicit ownership assignment + database RLS.
const select = { id: true, ownerId: true, title: true, body: true, createdAt: true } as const;

export const listNotes = (user: AuthedUser) =>
  withUser(user, (tx) => tx.sandboxNote.findMany({ select, orderBy: { createdAt: "asc" } }));

export const getNote = (user: AuthedUser, id: string) =>
  withUser(user, (tx) => tx.sandboxNote.findUnique({ where: { id }, select }));

export const createNote = (user: AuthedUser, input: { title: string; body?: string }) =>
  withUser(user, (tx) => tx.sandboxNote.create({ data: { ownerId: user.id, title: input.title, body: input.body ?? "" }, select }));

export const deleteNote = (user: AuthedUser, id: string) =>
  withUser(user, async (tx) => (await tx.sandboxNote.deleteMany({ where: { id } })).count);
