  const m8 = await req(`/api/notes/${B_NOTES[0]}`, { method: "DELETE", jar: a.jar });
  rec("M7", "DELETE B's note as A", "404", String(m8.status), m8.status === 404);

  // Own writes -------------------------------------------------------------------------------------------------------
  const created = await req("/api/notes", { method: "POST", jar: a.jar, ...jsonBody({ title: "temp from integration test" }) });
  const mine = created.data?.note;
  rec("W1", "POST /api/notes as A", "201, ownerId = A (from session)", `${created.status} owner=${mine?.ownerId}`, created.status === 201 && mine?.ownerId === A.id);
  const after = await req("/api/notes", { jar: a.jar });
  rec("W2", "created note is visible to A", "3 notes", String(ids(after.data).length), ids(after.data).length === 3);
  const del = mine ? await req(`/api/notes/${mine.id}`, { method: "DELETE", jar: a.jar }) : null;
  rec("W3", "DELETE own note", "200", String(del?.status), del?.status === 200);
  const csrfPost = await req("/api/notes", { method: "POST", jar: a.jar, origin: "http://evil.example", ...jsonBody({ title: "csrf" }) });
  const ctype = await req("/api/notes", { method: "POST", jar: a.jar, headers: { "content-type": "text/plain" }, body: JSON.stringify({ title: "x" }) });
  rec("W4", "POST from a foreign Origin / non-JSON content-type", "403 / 415", `${csrfPost.status} / ${ctype.status}`, csrfPost.status === 403 && ctype.status === 415);
}

// ---- 4. User B isolation (separate session) ---------------------------------------------------------------------------------
{
  const b = await loginAs(B);
  const list = await req("/api/notes", { jar: b.jar });
  rec("B1", "GET /api/notes as B", "exactly B's 2 notes", ids(list.data).join(","), eq(ids(list.data), B_NOTES));
  const peek = await req(`/api/notes/${A_NOTES[0]}`, { jar: b.jar });
  const del = await req(`/api/notes/${A_NOTES[0]}`, { method: "DELETE", jar: b.jar });
  rec("B2", "B reads / deletes A's note", "404 / 404", `${peek.status} / ${del.status}`, peek.status === 404 && del.status === 404);
  const aAgain = await req(`/api/notes/${A_NOTES[0]}`, { jar: a.jar });
  rec("B3", "A's note survived B's attempts", "200", String(aAgain.status), aAgain.status === 200);
}

// ---- 5. Cookie / token tampering ------------------------------------------------------------------------------------------------
{
  const session = readSession(a.jar);
  const parts = session.access_token.split(".");
  const claims = JSON.parse(Buffer.from(parts[1], "base64url").toString());

  const swapped = `${parts[0]}.${b64url({ ...claims, sub: B.id })}.${parts[2]}`;
  const t1 = await req("/api/notes", { jar: jarWithSession({ ...session, access_token: swapped }) });
  rec("C1", "access token payload edited to sub=<B> (signature kept)", "never B's data (401, or A's own via refresh)", `${t1.status} ${ids(t1.data).join(",")}`, t1.status === 401 || (t1.status === 200 && eq(ids(t1.data), A_NOTES)));

  const t2 = await req("/api/notes", { jar: jarWithSession({ ...session, user: { ...session.user, id: B.id, email: B.email } }) });
  rec("C2", "unsigned `user` object in the cookie edited to B", "ignored: identity comes from the verified token (A's rows)", `${t2.status} ${ids(t2.data).join(",")}`, t2.status === 200 && eq(ids(t2.data), A_NOTES));

  const forged = signJwt({ ...claims, sub: B.id, session_id: randomUUID() }, "not-the-real-secret");
  const t3 = await req("/api/notes", { jar: jarWithSession({ access_token: forged, refresh_token: "bogus", token_type: "bearer", expires_in: 3600, expires_at: claims.exp, user: { id: B.id } }) });
  rec("C3", "JWT for B signed with the wrong secret", "401", String(t3.status), t3.status === 401);

  const expired = signJwt({ ...claims, exp: Math.floor(Date.now() / 1000) - 3600, iat: Math.floor(Date.now() / 1000) - 7200 }, LOCAL_JWT_SECRET);
  const expiredJar = jarWithSession({ access_token: expired, refresh_token: "bogus", token_type: "bearer", expires_in: 3600, expires_at: Math.floor(Date.now() / 1000) - 3600, user: session.user });
  const t4 = await req("/api/notes", { jar: expiredJar });
  const t5 = await req("/notes", { jar: new Map(expiredJar) });
  rec("C4", "expired access token with an invalid refresh token", "API 401, page redirect to /login", `${t4.status}, ${t5.status} ${t5.location}`, t4.status === 401 && [302, 303, 307, 308].includes(t5.status) && !!t5.location?.endsWith("/login"));

  const garbage = await req("/api/notes", { jar: new Map([[COOKIE_NAME, "base64-not-json"]]) });
  rec("C5", "garbage session cookie", "401, no 500", String(garbage.status), garbage.status === 401);
}

// ---- 6. Logout and session invalidation ------------------------------------------------------------------------------------------
{
  const l = await loginAs(A);
  const replay = new Map(l.jar);
  const out = await req("/auth/logout", { method: "POST", jar: l.jar });
  rec("O1", "logout", "303 /login, session cookies cleared", `${out.status} ${out.location}, remaining=${l.jar.size}`, out.status === 303 && !!out.location?.endsWith("/login") && l.jar.size === 0);
  const rep = await req("/api/notes", { jar: replay });
  rec("O2", "replaying the pre-logout cookie", "401 (session revoked server-side)", String(rep.status), rep.status === 401);
  const csrf = await req("/auth/logout", { method: "POST", jar: new Map(), origin: "http://evil.example" });
  rec("O3", "logout POST from a foreign Origin", "403", String(csrf.status), csrf.status === 403);

  const one = await loginAs(A);
  const two = await loginAs(A);
  const pre = await req("/api/notes", { jar: two.jar });
  const token = readSession(one.jar).access_token;
  const revoke = await fetch(`${SUPABASE}/auth/v1/logout?scope=global`, { method: "POST", headers: { apikey: ANON, authorization: `Bearer ${token}` } });
  const s1 = await req("/api/notes", { jar: one.jar });
  const s2 = await req("/api/notes", { jar: two.jar });
  rec("O4", "global sign-out from another device revokes every session (JWTs not yet expired)", "before 200; after 401 / 401", `before ${pre.status}; revoke ${revoke.status}; after ${s1.status} / ${s2.status}`, pre.status === 200 && s1.status === 401 && s2.status === 401);
}

// ---- 7. Secrets in client bundles -------------------------------------------------------------------------------------------------
{
  const infraEnv = readFileSync(join(homedir(), "ezyfusion-infra-sandbox/.env"), "utf8");
  const serviceKey = infraEnv.match(/^SUPABASE_SERVICE_ROLE_KEY="(.*)"$/m)?.[1] ?? "";
  const needles: Record<string, string> = {
    "service-role key": serviceKey,
    "DB URL/password": ["postgres", "postgres@"].join(":"),
    "DATABASE_URL name": "DATABASE_URL",
    "JWT secret": LOCAL_JWT_SECRET,
    "SERVICE_ROLE name": "SERVICE_ROLE",
  };
  const files: string[] = [];
  const walk = (dir: string, accept: (f: string) => boolean) => {
    for (const n of readdirSync(dir)) {
      const p = join(dir, n);
      if (statSync(p).isDirectory()) walk(p, accept);
      else if (accept(p)) files.push(p);
    }
  };
  walk(".next/static", () => true);
  walk(".next/server/app", (f) => /\.(html|rsc|segment\.rsc|meta)$/.test(f));
  const served = [(await req("/login")).text, (await req("/notes", { jar: a.jar })).text];
  const corpus = files.map((f) => readFileSync(f, "utf8")).concat(served);
  for (const [label, needle] of Object.entries(needles)) {
    const hits = corpus.filter((c) => needle && c.includes(needle)).length;
    rec(`X-${label}`, `${label} absent from client bundles, prerendered output and served HTML`, "0 occurrences", `${hits} (scanned ${files.length} files + 2 pages)`, needle !== "" && hits === 0);
  }
  const anonHits = corpus.filter((c) => c.includes(ANON)).length;
  rec("X-anon", "positive control: the public anon key IS in the client bundle (scanner works)", "> 0 occurrences", String(anonHits), anonHits > 0);
}

console.log("\nID  RESULT  CHECK  |  expected  |  actual");
for (const r of results) console.log(`${r.id.padEnd(4)} ${r.ok ? "PASS  " : "FAIL  "} ${r.check}  |  ${r.expected}  |  ${r.actual}`);
const failed = results.filter((r) => !r.ok).length;
console.log(`\n${results.length - failed}/${results.length} checks passed`);
process.exit(failed ? 1 : 0);
EOF
