  startDate: '2026-01-31',
  endDate: '2026-07-15',
  monthlyRentSen: 150000,
  depositSen: 300000,
  ...over,
})
const rent = (invoices: ScheduledInvoice[]) => invoices.filter((i) => i.kind === 'rent')
const starts = (invoices: ScheduledInvoice[]) => rent(invoices).map((i) => i.periodStart)

