import { PrismaPg } from "@prisma/adapter-pg";
import { PrismaClient } from "../generated/prisma/client";

/**
 * Server-side data access. SECURITY: this connection is the database OWNER and BYPASSES Row Level Security.
 * Authorization is NOT provided by the database here: every caller must first verify the Supabase user, resolve the
 * user's membership / tenant row and scope every query by org_id (and tenant) itself.
 * Never import this from client code (use `src/server/db.ts`, which is guarded by `server-only`, inside the app).
 */
export function createPrismaClient(connectionString = process.env.DATABASE_URL): PrismaClient {
  if (!connectionString) throw new Error("DATABASE_URL is not set");
  return new PrismaClient({ adapter: new PrismaPg({ connectionString }) });
}

const globalForPrisma = globalThis as unknown as { prisma?: PrismaClient };

export function getPrisma(): PrismaClient {
  globalForPrisma.prisma ??= createPrismaClient();
  return globalForPrisma.prisma;
}
EOF
cat > src/server/db.ts <<'EOF'
import "server-only";

// Entry point for app code (Server Components, Route Handlers, Server Actions). Fails the build if a client module imports it.
export { getPrisma } from "./prisma";
EOF
cat > scripts/seed.ts <<'EOF'
/**
 * Seeds the local database and Supabase Auth. Idempotent (fixed ids, existing rows are left alone).
 * Server-side only: uses SUPABASE_SECRET_KEY (bypasses RLS) and the owner database connection.
 * Run after `npx supabase db reset`:  npm run seed
 */
import { createHash } from "node:crypto";
import { createClient } from "@supabase/supabase-js";
import { generateSchedule } from "../src/lib/billing";
import { createPrismaClient } from "../src/server/prisma";

try {
  process.loadEnvFile(".env.local");
} catch {
  /* rely on the process environment */
}
const need = (name: string) => {
  const value = process.env[name];
  if (!value) throw new Error(`${name} is not set (cp .env.example .env.local)`);
  return value;
};
const supabaseUrl = need("NEXT_PUBLIC_SUPABASE_URL");
const secretKey = need("SUPABASE_SECRET_KEY");
const password = need("SEED_PASSWORD");

/** Deterministic UUID from a stable name, so the seed is reproducible and re-runnable. */
function id(name: string): string {
  const h = createHash("sha1").update(`ezyfusion-seed:${name}`).digest("hex");
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-5${h.slice(13, 16)}-a${h.slice(17, 20)}-${h.slice(20, 32)}`;
}
const day = (iso: string) => new Date(`${iso}T00:00:00Z`);

// ---- data ----------------------------------------------------------------------------------------------------------------
const ORG = { northwind: id("org:northwind"), beta: id("org:beta") };

const USERS = [
  { email: "manager@northwind.test", org: ORG.northwind, role: "manager" as const, name: "Northwind Manager" },
  { email: "staff@northwind.test", org: ORG.northwind, role: "staff" as const, name: "Northwind Staff" },
  { email: "aisyah@northwind.test", org: ORG.northwind, role: "tenant" as const, name: "Aisyah Rahman", phone: "+60123456781" },
  { email: "ben@northwind.test", org: ORG.northwind, role: "tenant" as const, name: "Ben Lim", phone: "+60123456782" },
  { email: "probe@northwind.test", org: ORG.northwind, role: "tenant" as const, name: "Probe Tenant", phone: "+60123456783" },
  { email: "manager@beta.test", org: ORG.beta, role: "manager" as const, name: "Beta Manager" },
  { email: "chen@beta.test", org: ORG.beta, role: "tenant" as const, name: "Chen Wei", phone: "+60123456784" },
].map((u) => ({ ...u, userId: id(`user:${u.email}`) }));
const user = (email: string) => USERS.find((u) => u.email === email)!;

const UNITS = [
  { key: "A-12-3", org: ORG.northwind },
  { key: "B-05-1", org: ORG.northwind },
  { key: "C-01-7", org: ORG.northwind },
  { key: "D-03-2", org: ORG.northwind }, // intentionally has no lease
  { key: "KL-1", org: ORG.beta },
].map((u) => ({ ...u, id: id(`unit:${u.org}:${u.key}`) }));

const LEASES = [
  { key: "aisyah", unit: "A-12-3", tenant: "aisyah@northwind.test", start: "2026-01-31", end: "2026-07-15", rent: 150000, deposit: 300000 },
  { key: "ben", unit: "B-05-1", tenant: "ben@northwind.test", start: "2026-01-01", end: "2026-04-15", rent: 100029, deposit: 0 },
  { key: "probe", unit: "C-01-7", tenant: "probe@northwind.test", start: "2026-02-28", end: "2027-02-27", rent: 200000, deposit: 400000 },
  { key: "chen", unit: "KL-1", tenant: "chen@beta.test", start: "2026-03-15", end: "2027-03-14", rent: 220000, deposit: 440000 },
].map((l) => {
  const tenant = user(l.tenant);
  return { ...l, org: tenant.org, id: id(`lease:${l.key}`), unitId: UNITS.find((u) => u.key === l.unit)!.id, tenantId: id(`tenant:${l.tenant}`) };
});

// 1x1 PNG used as the slip image (a real object in the private payment-slips bucket).
const SLIP_PNG = Buffer.from("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==", "base64");

// ---- run -------------------------------------------------------------------------------------------------------------------------
const admin = createClient(supabaseUrl, secretKey, { auth: { persistSession: false, autoRefreshToken: false } });
const prisma = createPrismaClient();

// 1. Auth users (fixed ids; password reset to the documented one on every run)
for (const u of USERS) {
  const existing = await admin.auth.admin.getUserById(u.userId);
  const attrs = { email: u.email, password, email_confirm: true, user_metadata: { full_name: u.name } };
  const { error } = existing.data.user
    ? await admin.auth.admin.updateUserById(u.userId, attrs)
    : await admin.auth.admin.createUser({ id: u.userId, ...attrs });
  if (error) throw new Error(`auth user ${u.email}: ${error.message}`);
}

// 2. Organizations, memberships, units, tenants, leases
await prisma.organization.createMany({
  data: [
    { id: ORG.northwind, name: "Northwind Properties" },
    { id: ORG.beta, name: "Beta Realty" },
  ],
  skipDuplicates: true,
});
await prisma.membership.createMany({
  data: USERS.filter((u) => u.role !== "tenant").map((u) => ({ userId: u.userId, orgId: u.org, role: u.role })),
  skipDuplicates: true,
});
await prisma.unit.createMany({ data: UNITS.map((u) => ({ id: u.id, orgId: u.org, name: u.key })), skipDuplicates: true });
await prisma.tenant.createMany({
  data: USERS.filter((u) => u.role === "tenant").map((u) => ({
    id: id(`tenant:${u.email}`),
    orgId: u.org,
    userId: u.userId,
    fullName: u.name,
    email: u.email,
    phone: u.phone,
  })),
  skipDuplicates: true,
});
await prisma.lease.createMany({
  data: LEASES.map((l) => ({
    id: l.id,
    orgId: l.org,
    unitId: l.unitId,
    tenantId: l.tenantId,
    startDate: day(l.start),
    endDate: day(l.end),
    monthlyRentSen: BigInt(l.rent),
    depositSen: BigInt(l.deposit),
  })),
  skipDuplicates: true,
});

// 3. Invoices come from the billing domain function, never a separate calculation.
for (const l of LEASES) {
  const schedule = generateSchedule({ startDate: l.start, endDate: l.end, monthlyRentSen: l.rent, depositSen: l.deposit });
  await prisma.invoice.createMany({
    data: schedule.map((s) => ({
      id: id(`invoice:${l.key}:${s.kind}:${s.periodIndex ?? "deposit"}`),
      orgId: l.org,
      leaseId: l.id,
      kind: s.kind,
      periodIndex: s.periodIndex,
      periodStart: s.periodStart ? day(s.periodStart) : null,
      periodEnd: s.periodEnd ? day(s.periodEnd) : null,
      dueDate: day(s.dueDate),
      amountSen: BigInt(s.amountSen),
    })),
    skipDuplicates: true,
  });
}

// 4. Aisyah's payments.
//    DEPENDENCY NOT IMPLEMENTED YET: payment allocation (applying a payment to invoices). The payment domain logic
//    is a later cycle, so no payment_allocations rows are created and each payment is stored fully UNAPPLIED
//    (unapplied_sen = amount_sen). Nothing here pretends invoices were settled.
const northwind = ORG.northwind;
const aisyah = LEASES.find((l) => l.key === "aisyah")!;
const manager = user("manager@northwind.test");
const staff = user("staff@northwind.test");
const cashId = id("payment:aisyah:cash");
const transferId = id("payment:aisyah:transfer");
const slipPath = `${northwind}/${transferId}.png`;

const upload = await admin.storage.from("payment-slips").upload(slipPath, SLIP_PNG, { contentType: "image/png", upsert: true });
if (upload.error) throw new Error(`slip upload: ${upload.error.message}`);

await prisma.payment.createMany({
  data: [
    // approved cash, received 2026-01-31 10:00 Malaysia time (UTC+8) = 02:00Z, recorded by the manager
    { id: cashId, orgId: northwind, leaseId: aisyah.id, amountSen: 300000n, unappliedSen: 300000n, method: "cash", status: "approved", receivedAt: new Date("2026-01-31T02:00:00Z") },
    // approved bank transfer, received 2026-03-01 00:30 Malaysia time = 2026-02-28T16:30Z, recorded by staff, approved by the manager
    { id: transferId, orgId: northwind, leaseId: aisyah.id, amountSen: 200000n, unappliedSen: 200000n, method: "bank_transfer", status: "approved", receivedAt: new Date("2026-02-28T16:30:00Z"), slipPath },
  ],
  skipDuplicates: true,
});

// 5. Audit trail (append-only; fixed ids + timestamps so re-running the seed adds nothing).
await prisma.auditLog.createMany({
  data: [
    ...LEASES.map((l, i) => ({
      id: id(`audit:lease-created:${l.key}`),
      orgId: l.org,
      actorId: l.org === ORG.beta ? user("manager@beta.test").userId : manager.userId,
      action: "lease.created",
      entityId: l.id,
      details: { unit: l.unit, startDate: l.start, endDate: l.end },
      createdAt: new Date(`2026-01-0${i + 1}T01:00:00Z`),
    })),
    { id: id("audit:payment-recorded:cash"), orgId: northwind, actorId: manager.userId, action: "payment.recorded", entityId: cashId, details: { amountSen: 300000, method: "cash" }, createdAt: new Date("2026-01-31T02:05:00Z") },
    { id: id("audit:payment-approved:cash"), orgId: northwind, actorId: manager.userId, action: "payment.approved", entityId: cashId, details: { approvedBy: "manager" }, createdAt: new Date("2026-01-31T02:06:00Z") },
    { id: id("audit:payment-recorded:transfer"), orgId: northwind, actorId: staff.userId, action: "payment.recorded", entityId: transferId, details: { amountSen: 200000, method: "bank_transfer", slipPath }, createdAt: new Date("2026-02-28T16:45:00Z") },
    { id: id("audit:payment-approved:transfer"), orgId: northwind, actorId: manager.userId, action: "payment.approved", entityId: transferId, details: { approvedBy: "manager" }, createdAt: new Date("2026-03-01T01:00:00Z") },
  ],
  skipDuplicates: true,
});

const counts = {
  organizations: await prisma.organization.count(),
  memberships: await prisma.membership.count(),
  units: await prisma.unit.count(),
  tenants: await prisma.tenant.count(),
  leases: await prisma.lease.count(),
  invoices: await prisma.invoice.count(),
  payments: await prisma.payment.count(),
  paymentAllocations: await prisma.paymentAllocation.count(),
  auditLog: await prisma.auditLog.count(),
};
console.log("seed complete:", JSON.stringify(counts));
console.log("note: payment allocation is not implemented yet; seeded payments are fully unapplied (payment_allocations is empty).");
await prisma.$disconnect();
EOF
