const fs=require("fs");const p=JSON.parse(fs.readFileSync("package.json"));
Object.assign(p.scripts,{"seed":"tsx scripts/seed.ts","db:check":"prisma validate && prisma generate && tsx scripts/check-prisma-schema.ts","db:reset":"supabase db reset"});
fs.writeFileSync("package.json",JSON.stringify(p,null,2)+"\n")'
echo "== supabase db reset (workflow step)"; npx supabase db reset 2>&1 | tail -6; echo "== seed"; npm run seed 2>&1 | tail -8

