    expect((await rest(`audit_log?id=eq.${anyAuditId}`, { token: managerToken, method: "DELETE" })).status).toBe(403);
    expect((await rest("audit_log", { token: managerToken, method: "POST", body: { org_id: nw, action: "forged" } })).status).toBe(403);
