    expect((await upload(`${beta}/x-${randomUUID()}.png`, tok["manager@northwind.test"])).status).toBeGreaterThanOrEqual(400);
    expect((await upload(`${nw}/x-${randomUUID()}.png`, tok["manager@beta.test"])).status).toBeGreaterThanOrEqual(400);
