  id: billId,
  paid: String(paid),
  paid_amount: amount,
  paid_at: paidAt,
  transaction_id: `TX-${randomBytes(4).toString('hex').toUpperCase()}`,
  transaction_status: paid ? 'completed' : 'failed',
