    const result = await postJson(`/api/payments/${paymentId}/${action}`, body)
    if (!result.ok) {
      const message = describeFailure(result.status, result.error)
      toast.error(message)
      router.refresh() // the payment may have changed meanwhile
      return message
    }
    toast.success(success)
    router.refresh()
    return null
