    try {
      amountSen = parseRinggitToSen(amount)
      if (amountSen <= 0) next.amount = 'Amount must be greater than zero.'
    } catch {
      next.amount = 'Enter a valid amount in ringgit, for example 1,500.50 (at most 2 decimals).'
