    expect((await api(`/api/leases/${lease.id}/payments`, { token: ctx.tok["manager@northwind.test"], body: { amountSen: 12345, method: "cash", receivedAt: new Date().toISOString().replace("Z", "+00:00") } })).status).toBe(201);
