import { PaymentStatusBadge } from '@/components/status-badges'
import { Table, TableBody, TableCaption, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table'
import type { LeaseDetail } from '@/server/domain/leases'
import { formatInstantMy, formatRM } from '@/lib/format-my'
import { PaymentActions } from './payment-actions'
import { SlipLink } from './slip-link'

const METHOD: Record<string, string> = { cash: 'Cash', bank_transfer: 'Bank transfer', online: 'Online' }

interface Props {
  payments: LeaseDetail['payments']
  /** payment id -> slip path (staff/managers only) */
  slipPaths?: Record<string, string>
  /** Manager-only controls (approve / reject / void). Never true for staff or tenants. */
  canManage?: boolean
}

export function PaymentTable({ payments, slipPaths = {}, canManage = false }: Props) {
  if (payments.length === 0) return <p className="p-4 text-sm text-muted-foreground">No payments yet.</p>
  return (
    <Table data-testid="payment-table">
      <TableCaption className="sr-only">Payments</TableCaption>
      <TableHeader>
        <TableRow className="hover:bg-transparent">
          <TableHead scope="col" className="px-4">Method</TableHead>
          <TableHead scope="col" className="px-4 text-right">Amount</TableHead>
          <TableHead scope="col" className="px-4">Received (Malaysia time)</TableHead>
          <TableHead scope="col" className="px-4">Status</TableHead>
          <TableHead scope="col" className="px-4">Slip</TableHead>
          {canManage ? <TableHead scope="col" className="px-4"><span className="sr-only">Actions</span></TableHead> : null}
        </TableRow>
      </TableHeader>
      <TableBody>
        {payments.map((p) => (
          <TableRow key={p.id} data-testid="payment-row" data-status={p.status} data-payment-id={p.id}>
            <TableCell className="px-4">{METHOD[p.method] ?? p.method}</TableCell>
            <TableCell className="px-4 text-right tabular-nums">
              {formatRM(p.amountSen)}
              {p.unappliedSen > 0 ? <span className="block text-xs text-muted-foreground-strong">{formatRM(p.unappliedSen)} unapplied</span> : null}
            </TableCell>
            <TableCell className="px-4">{formatInstantMy(p.receivedAt)}</TableCell>
            <TableCell className="px-4">
              <PaymentStatusBadge status={p.status} />
            </TableCell>
            <TableCell className="px-4">{p.method === 'bank_transfer' && slipPaths[p.id] ? <SlipLink path={slipPaths[p.id]} /> : <span className="text-muted-foreground-strong">—</span>}</TableCell>
            {canManage ? (
              <TableCell className="px-4">
                <PaymentActions paymentId={p.id} status={p.status} amountLabel={formatRM(p.amountSen)} />
              </TableCell>
            ) : null}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  )
}
'use client'

import { useRouter } from 'next/navigation'
import { useState } from 'react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { describeFailure, postJson } from '@/lib/api-client'
import { ReasonDialog } from './reason-dialog'

interface Props {
  paymentId: string
  status: string
  amountLabel: string
}

/** Manager-only controls. The server enforces the role too; staff never receive this component. */
export function PaymentActions({ paymentId, status, amountLabel }: Props) {
  const router = useRouter()
  const [busy, setBusy] = useState(false)

  async function run(action: 'approve' | 'reject' | 'void', body: unknown, success: string): Promise<string | null> {
    const result = await postJson(`/api/payments/${paymentId}/${action}`, body)
    if (!result.ok) {
      const message = describeFailure(result.status, result.error)
      toast.error(message)
      router.refresh() // the payment may have changed meanwhile
      return message
    }
    toast.success(success)
    router.refresh()
    return null
  }

  if (status === 'pending_verification') {
    return (
      <div className="flex flex-wrap gap-2">
        <Button type="button" disabled={busy} data-testid="approve-payment" onClick={async () => { setBusy(true); await run('approve', {}, `Payment of ${amountLabel} approved`); setBusy(false) }}>
          Approve
        </Button>
        <ReasonDialog
          trigger={<Button type="button" variant="outline" data-testid="reject-payment">Reject</Button>}
          title="Reject payment"
          description={`Reject the pending payment of ${amountLabel}. The reason is kept in the audit log.`}
          confirmLabel="Reject payment"
          destructive
          onConfirm={(reason) => run('reject', { reason }, 'Payment rejected')}
        />
      </div>
    )
  }
  if (status === 'approved') {
    return (
      <ReasonDialog
        trigger={<Button type="button" variant="outline" data-testid="void-payment">Void</Button>}
        title="Void this payment?"
        description={`This removes the payment of ${amountLabel} from the invoices it paid. Other payments are not reallocated. This cannot be undone.`}
        confirmLabel="Void payment"
        destructive
        onConfirm={(reason) => run('void', { reason }, 'Payment voided')}
      />
    )
  }
  return null
}
'use client'

import { useRouter } from 'next/navigation'
import { useMemo, useRef, useState, useSyncExternalStore, type FormEvent } from 'react'
import { toast } from 'sonner'
import { cleanupSlip } from '@/app/actions/slips'
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { describeFailure, postJson } from '@/lib/api-client'
import { parseRinggitToSen } from '@/lib/billing'
import { formatRM, malaysiaInputToIso, toMalaysiaInputValue } from '@/lib/format-my'
import { createClient } from '@/lib/supabase/browser'

const SLIP_TYPES: Record<string, string> = { 'image/jpeg': 'jpg', 'image/png': 'png', 'application/pdf': 'pdf' }
const SLIP_MAX = 5 * 1024 * 1024
const METHODS = [
  { value: 'cash', label: 'Cash' },
  { value: 'bank_transfer', label: 'Bank transfer' },
]

type Errors = Partial<Record<'amount' | 'receivedAt' | 'slip', string>>

interface Props {
  leaseId: string
  /** Organization folder for slips (the organization id is not a secret; Storage RLS enforces the rest). */
  orgId: string
  role: 'manager' | 'staff'
}

export function PaymentForm({ leaseId, orgId, role }: Props) {
  const router = useRouter()
  const fileRef = useRef<HTMLInputElement>(null)
  const [method, setMethod] = useState<string>('cash')
  const [amount, setAmount] = useState('')
  // Default "received" time = now in Malaysia time. It is only computed on the client (never during server rendering), so
  // there is no hydration mismatch; until the user edits the field, the default is used.
  const mounted = useSyncExternalStore(() => () => undefined, () => true, () => false)
  const defaultReceivedAt = useMemo(() => (mounted ? toMalaysiaInputValue(new Date()) : ''), [mounted])
  const [receivedEdit, setReceivedEdit] = useState<string | null>(null)
  const receivedAt = receivedEdit ?? defaultReceivedAt
  const setReceivedAt = setReceivedEdit
  const [file, setFile] = useState<File | null>(null)
  const [errors, setErrors] = useState<Errors>({})
  const [formError, setFormError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState(false)

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (submitting) return
    setFormError(null)
    const next: Errors = {}

    let amountSen = 0
    try {
      amountSen = parseRinggitToSen(amount)
      if (amountSen <= 0) next.amount = 'Amount must be greater than zero.'
    } catch {
      next.amount = 'Enter a valid amount in ringgit, for example 1,500.50 (at most 2 decimals).'
    }
    const iso = malaysiaInputToIso(receivedAt)
    if (!iso) next.receivedAt = 'Enter the date and time the payment was received (Malaysia time).'
    if (method === 'bank_transfer') {
      if (!file) next.slip = 'Attach the bank transfer slip (JPEG, PNG or PDF).'
      else if (!(file.type in SLIP_TYPES)) next.slip = 'The slip must be a JPEG, PNG or PDF file.'
      else if (file.size > SLIP_MAX) next.slip = 'The slip must be 5 MB or smaller.'
      else if (file.size === 0) next.slip = 'The selected file is empty.'
    }
    setErrors(next)
    if (Object.keys(next).length > 0 || !iso) return

    setSubmitting(true)
    let uploaded: string | null = null
    try {
      if (method === 'bank_transfer' && file) {
        const path = `${orgId}/${crypto.randomUUID()}.${SLIP_TYPES[file.type]}`
        const { error } = await createClient().storage.from('payment-slips').upload(path, file, { contentType: file.type, upsert: false })
        if (error) {
          fail('Could not upload the slip. Check the file and try again.')
          return
        }
        uploaded = path
      }
      const result = await postJson<{ id: string; status: string }>(`/api/leases/${leaseId}/payments`, {
        amountSen,
        method,
        receivedAt: iso,
        ...(uploaded ? { slipPath: uploaded } : {}),
      })
      if (!result.ok || !result.data) {
        // the server removes unreferenced slips itself after a failed recording; this covers rejections before that point.
        if (uploaded) await cleanupSlip(uploaded).catch(() => undefined)
        fail(describeFailure(result.status, result.error))
        return
      }
      toast.success(result.data.status === 'approved' ? `Payment of ${formatRM(amountSen)} recorded and approved` : `Payment of ${formatRM(amountSen)} recorded, pending verification`)
      setAmount('')
      setFile(null)
      if (fileRef.current) fileRef.current.value = ''
      setReceivedAt(toMalaysiaInputValue(new Date()))
      router.refresh()
    } finally {
      setSubmitting(false)
    }
  }

  function fail(message: string) {
    setFormError(message)
    toast.error(message)
    setSubmitting(false)
  }

  return (
    <form onSubmit={onSubmit} noValidate className="space-y-4" data-testid="payment-form">
      <p className="text-sm text-muted-foreground">
        {role === 'manager' ? 'Payments you record are approved immediately.' : 'Payments you record wait for a manager to verify them.'}
      </p>
      {formError ? (
        <Alert variant="destructive" role="alert">
          <AlertTitle>Payment not recorded</AlertTitle>
          <AlertDescription>{formError}</AlertDescription>
        </Alert>
      ) : null}
      <div className="grid gap-x-4 gap-y-3 md:grid-cols-3">
        <div className="space-y-1.5">
          <Label htmlFor="pay-method">Method</Label>
          <Select items={METHODS} value={method} onValueChange={(v) => { setMethod(v ?? 'cash'); setErrors((e) => ({ ...e, slip: undefined })) }}>
            <SelectTrigger id="pay-method">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {METHODS.map((m) => (
                <SelectItem key={m.value} value={m.value}>{m.label}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-1.5">
          <Label htmlFor="pay-amount">Amount (RM)</Label>
          <Input id="pay-amount" inputMode="decimal" autoComplete="off" className="text-right tabular-nums" placeholder="1,500.50" value={amount} onChange={(e) => setAmount(e.target.value)} aria-invalid={errors.amount ? true : undefined} aria-describedby={errors.amount ? 'pay-amount-error' : undefined} />
          {errors.amount ? <p id="pay-amount-error" className="text-sm text-destructive">{errors.amount}</p> : null}
        </div>
        <div className="space-y-1.5">
          <Label htmlFor="pay-received">Received (Malaysia time, UTC+8)</Label>
          <Input id="pay-received" type="datetime-local" value={receivedAt} onChange={(e) => setReceivedAt(e.target.value)} aria-invalid={errors.receivedAt ? true : undefined} aria-describedby={errors.receivedAt ? 'pay-received-error' : undefined} />
          {errors.receivedAt ? <p id="pay-received-error" className="text-sm text-destructive">{errors.receivedAt}</p> : null}
        </div>
      </div>
      {method === 'bank_transfer' ? (
        <div className="space-y-1.5">
          <Label htmlFor="pay-slip">Transfer slip (JPEG, PNG or PDF, max 5 MB)</Label>
          <Input id="pay-slip" ref={fileRef} type="file" accept="image/jpeg,image/png,application/pdf" onChange={(e) => setFile(e.target.files?.[0] ?? null)} aria-invalid={errors.slip ? true : undefined} aria-describedby={errors.slip ? 'pay-slip-error' : undefined} />
          {errors.slip ? <p id="pay-slip-error" className="text-sm text-destructive">{errors.slip}</p> : null}
        </div>
      ) : null}
      <Button type="submit" disabled={submitting} aria-busy={submitting} data-testid="record-payment">
        {submitting ? 'Recording…' : 'Record payment'}
      </Button>
    </form>
  )
}
