'use client'

import { useState, type ReactNode } from 'react'
import { Button } from '@/components/ui/button'
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'

const MIN = 5

interface Props {
  trigger: ReactNode
  title: string
  description: string
  confirmLabel: string
  destructive?: boolean
  /** Return an error message to keep the dialog open, or null when the action succeeded. */
  onConfirm: (reason: string) => Promise<string | null>
}

/** Confirmation dialog that collects a reason of at least 5 characters. */
export function ReasonDialog({ trigger, title, description, confirmLabel, destructive, onConfirm }: Props) {
  const [open, setOpen] = useState(false)
  const [reason, setReason] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [busy, setBusy] = useState(false)

  async function submit() {
    const trimmed = reason.trim()
    if (trimmed.length < MIN) {
      setError(`Enter a reason of at least ${MIN} characters.`)
      return
    }
    setBusy(true)
    setError(null)
    const failure = await onConfirm(trimmed)
    setBusy(false)
    if (failure) {
      setError(failure)
      return
    }
    setOpen(false)
    setReason('')
  }

  return (
    <Dialog open={open} onOpenChange={(next) => { setOpen(next); if (!next) { setError(null); setReason('') } }}>
      <DialogTrigger render={trigger as React.ReactElement} />
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          <DialogDescription>{description}</DialogDescription>
        </DialogHeader>
        <div className="space-y-1.5">
          <Label htmlFor="reason-input">Reason (at least {MIN} characters)</Label>
          <Textarea id="reason-input" value={reason} onChange={(e) => setReason(e.target.value)} aria-invalid={error ? true : undefined} aria-describedby={error ? 'reason-error' : undefined} maxLength={500} />
          {error ? <p id="reason-error" role="alert" className="text-sm text-destructive">{error}</p> : null}
        </div>
        <DialogFooter>
          <Button type="button" variant="outline" onClick={() => setOpen(false)} disabled={busy}>Cancel</Button>
          <Button type="button" variant={destructive ? 'destructive' : 'default'} onClick={submit} disabled={busy} data-testid="reason-confirm">
            {busy ? 'Working…' : confirmLabel}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}
'use client'

import Link from 'next/link'
import { useState } from 'react'
import { toast } from 'sonner'
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert'
import { Button } from '@/components/ui/button'
import { describeFailure, postJson } from '@/lib/api-client'
import { formatRM } from '@/lib/format-my'

interface Bill {
  billId: string
  amountSen: number
}

export function PayNow({ leaseId, dueNowSen }: { leaseId: string; dueNowSen: number }) {
  const [busy, setBusy] = useState(false)
  const [bill, setBill] = useState<Bill | null>(null)
  const [error, setError] = useState<string | null>(null)

  async function create() {
    setBusy(true)
    setError(null)
    const result = await postJson<Bill>(`/api/leases/${leaseId}/gateway-bills`)
    setBusy(false)
    if (!result.ok || !result.data) {
      const message = result.status === 422 ? 'Nothing is due on this lease right now.' : describeFailure(result.status, result.error)
      setError(message)
      toast.error(message)
      return
    }
    setBill(result.data)
    toast.success(`Payment bill created for ${formatRM(result.data.amountSen)}`)
  }

  return (
    <div className="space-y-3" data-testid="pay-now">
      <p>
        Amount due now: <strong data-testid="due-now">{formatRM(dueNowSen)}</strong>
      </p>
      <Button type="button" onClick={create} disabled={busy || dueNowSen <= 0} aria-busy={busy} data-testid="pay-now-button">
        {busy ? 'Creating bill…' : 'Pay now'}
      </Button>
      {dueNowSen <= 0 ? <p className="text-sm text-muted-foreground">Nothing is due right now.</p> : null}
      {error ? (
        <Alert variant="destructive" role="alert">
          <AlertTitle>Could not create the bill</AlertTitle>
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      ) : null}
      {bill ? (
        <Alert variant="success" data-testid="bill-created">
          <AlertTitle>Payment bill created</AlertTitle>
          <AlertDescription className="space-y-1">
            <p>
              Bill ID: <code data-testid="bill-id">{bill.billId}</code>
            </p>
            <p>
              Amount: <strong>{formatRM(bill.amountSen)}</strong>
            </p>
            <p>
              <Link className="underline underline-offset-2" href={`/payments/return?bill_id=${bill.billId}`} data-testid="bill-return-link">
                Check payment status
              </Link>
            </p>
          </AlertDescription>
        </Alert>
      ) : null}
    </div>
  )
}
'use client'

import { useRouter } from 'next/navigation'
import { useState, type FormEvent } from 'react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { createClient } from '@/lib/supabase/browser'

/**
 * Updates the tenant's own phone number straight from the browser with the user's session (publishable key): the database
 * allows exactly this write (column-level UPDATE(phone) grant + own-row RLS policy). The service role is never involved.
 */
export function PhoneForm({ tenantId, phone }: { tenantId: string; phone: string | null }) {
  const router = useRouter()
  const [value, setValue] = useState(phone ?? '')
  const [error, setError] = useState<string | null>(null)
  const [busy, setBusy] = useState(false)

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const trimmed = value.trim()
    if (trimmed.length > 32) {
      setError('A phone number can have at most 32 characters.')
      return
    }
    if (trimmed !== '' && !/^[+0-9 ()-]{3,32}$/.test(trimmed)) {
      setError('Use digits, spaces, + ( ) and - only, for example +60 12 345 6789.')
      return
    }
    setError(null)
    setBusy(true)
    const { data, error: updateError } = await createClient().from('tenants').update({ phone: trimmed === '' ? null : trimmed }).eq('id', tenantId).select('phone')
    setBusy(false)
    if (updateError || !data || data.length !== 1) {
      const message = 'Could not update your phone number.'
      setError(message)
      toast.error(message)
      return
    }
    toast.success('Phone number updated')
    router.refresh()
  }

  return (
    <form onSubmit={onSubmit} noValidate className="space-y-3" data-testid="phone-form">
      <div className="space-y-1.5">
        <Label htmlFor="tenant-phone">Phone number</Label>
        <Input id="tenant-phone" type="tel" autoComplete="tel" value={value} onChange={(e) => setValue(e.target.value)} aria-invalid={error ? true : undefined} aria-describedby={error ? 'tenant-phone-error' : undefined} />
        {error ? <p id="tenant-phone-error" role="alert" className="text-sm text-destructive">{error}</p> : null}
      </div>
      <Button type="submit" disabled={busy} aria-busy={busy} data-testid="save-phone">
        {busy ? 'Saving…' : 'Save phone number'}
      </Button>
    </form>
  )
}
