import { Suspense, type ReactNode } from 'react'
import { redirect } from 'next/navigation'
import { Skeleton } from '@/components/ui/skeleton'
import { getViewer } from '@/server/http/session'

async function PortalRedirect(): Promise<ReactNode> {
  const viewer = await getViewer()
  if (!viewer || viewer.portal === 'none') redirect('/login')
  redirect(viewer.portal === 'tenant' ? '/portal' : '/dashboard')
}

/** Sends each signed-in role to its own portal. */
export default function Home() {
  return (
    <Suspense fallback={<Skeleton className="h-24 w-full" />}>
      <PortalRedirect />
    </Suspense>
  )
}
import 'server-only'
import { createServerClient } from '@supabase/ssr'
import { cache } from 'react'
import { cookies } from 'next/headers'
import { getPrisma } from '../db'
import { resolveViewer, type ViewerProfile } from '../domain/viewer'

export interface SessionUser {
  id: string
  email: string | undefined
}

/** Verified user from the SSR session cookies (Server Components). getUser() validates with the Auth server. */
export const sessionUser = cache(async (): Promise<SessionUser | null> => {
  const store = await cookies()
  if (store.getAll().length === 0) return null
  const supabase = createServerClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY!, {
    cookies: { getAll: () => store.getAll(), setAll: () => undefined },
  })
  const { data, error } = await supabase.auth.getUser()
  return error || !data.user ? null : { id: data.user.id, email: data.user.email }
})

export async function sessionUserId(): Promise<string | null> {
  return (await sessionUser())?.id ?? null
}

/** Verified user + roles resolved from memberships / tenants (never from user_metadata). Cached per request. */
export const getViewer = cache(async (): Promise<(ViewerProfile & { email: string | undefined }) | null> => {
  const user = await sessionUser()
  if (!user) return null
  return { ...(await resolveViewer(getPrisma(), user.id)), email: user.email }
})
import 'server-only'
import { notFound, redirect } from 'next/navigation'
import { HttpError } from '../domain/errors'
import { getViewer } from './session'

export type PageViewer = NonNullable<Awaited<ReturnType<typeof getViewer>>>

/**
 * Page-level role guard. Unauthenticated visitors go to /login; a signed-in user in the wrong portal is sent to their own.
 * (The data functions behind each page authorize again; this only decides where a user belongs.)
 */
export async function requirePortal(kind: 'staff' | 'tenant'): Promise<PageViewer> {
  const viewer = await getViewer()
  if (!viewer) redirect('/login')
  if (viewer.portal === 'none') redirect('/login')
  const isStaff = viewer.portal === 'manager' || viewer.portal === 'staff'
  if (kind === 'staff' && !isStaff) redirect('/portal')
  if (kind === 'tenant' && isStaff) redirect('/dashboard')
  return viewer
}

/** Runs a read-model query; a 404/403 from the domain layer becomes the framework's not-found page. */
export async function orNotFound<T>(run: () => Promise<T>): Promise<T> {
  try {
    return await run()
  } catch (e) {
    if (e instanceof HttpError && (e.status === 404 || e.status === 403)) notFound()
    throw e
  }
}
