          data: {
            orgId: unit.orgId,
            actorId: actorUserId,
            action: 'lease.created',
            entityId: leaseId,
            details: { unitId: unit.id, tenantId: tenant.id, startDate: input.startDate, endDate: input.endDate, monthlyRentSen: input.monthlyRentSen, depositSen: input.depositSen, invoices: schedule.length },
