    const dueDate = dateOnly(i.dueDate)
    return {
      id: i.id,
      kind: i.kind as InvoiceKind,
      periodIndex: i.periodIndex,
      periodStart: i.periodStart ? dateOnly(i.periodStart) : null,
      periodEnd: i.periodEnd ? dateOnly(i.periodEnd) : null,
      dueDate,
      amountSen,
