/** Browser-side helper for the app's own JSON API. Cookies authenticate (same origin); errors carry the server's message. */
export interface ApiResult<T> {
  ok: boolean
  status: number
  data: T | null
  error: string | null
}

export async function postJson<T = Record<string, unknown>>(path: string, body: unknown = {}): Promise<ApiResult<T>> {
  try {
    const res = await fetch(path, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body), credentials: 'same-origin' })
    const data: unknown = await res.json().catch(() => null)
    const error = !res.ok && data && typeof data === 'object' && 'error' in data && typeof (data as { error: unknown }).error === 'string' ? (data as { error: string }).error : null
    return { ok: res.ok, status: res.status, data: res.ok ? (data as T) : null, error: res.ok ? null : (error ?? `Request failed (${res.status})`) }
  } catch {
    return { ok: false, status: 0, data: null, error: 'Network error. Check your connection and try again.' }
  }
}

/** Friendly text for the API's status codes. */
export function describeFailure(status: number, serverMessage: string | null): string {
  switch (status) {
    case 401:
      return 'Your session has expired. Please sign in again.'
    case 403:
      return 'You are not allowed to do this.'
    case 404:
      return 'This item was not found.'
    case 409:
      return serverMessage ?? 'This item changed in the meantime. Refresh and try again.'
    case 422:
      return serverMessage ?? 'The amount is more than the lease can accept.'
    case 0:
      return serverMessage ?? 'Network error.'
    default:
      return serverMessage ?? 'Something went wrong. Please try again.'
  }
}
/**
 * Authorization lookups. Prisma connects as the database owner and BYPASSES RLS, so every decision about who may
 * see or do what is made here, from rows in memberships / tenants, never from client-supplied roles or org ids.
 */
import type { Db } from './db'
import { isUuid } from './convert'
import { notFound } from './errors'

export type LeaseRole = 'manager' | 'staff' | 'tenant'

export interface LeaseRow {
  id: string
  orgId: string
  unitId: string
  tenantId: string
  startDate: Date
  endDate: Date
  monthlyRentSen: bigint
  depositSen: bigint
}

export const orgIdsWithRole = async (db: Db, userId: string, roles: ('manager' | 'staff')[]): Promise<string[]> =>
  (await db.membership.findMany({ where: { userId, role: { in: roles } }, select: { orgId: true } })).map((m) => m.orgId)

/** A visible lease plus the caller's role on it; throws 404 when the caller may not see it (or it does not exist). */
export async function resolveLeaseAccess(db: Db, userId: string, leaseId: string): Promise<{ lease: LeaseRow; role: LeaseRole }> {
  if (!isUuid(leaseId)) throw notFound('lease not found')
  const lease = await db.lease.findUnique({ where: { id: leaseId } })
  if (!lease) throw notFound('lease not found')
  const membership = await db.membership.findUnique({ where: { userId_orgId: { userId, orgId: lease.orgId } }, select: { role: true } })
  if (membership?.role === 'manager' || membership?.role === 'staff') return { lease, role: membership.role }
  const tenant = await db.tenant.findFirst({ where: { id: lease.tenantId, orgId: lease.orgId, userId }, select: { id: true } })
  if (tenant) return { lease, role: 'tenant' }
  throw notFound('lease not found')
}

export async function resolvePaymentAccess(db: Db, userId: string, paymentId: string) {
  if (!isUuid(paymentId)) throw notFound('payment not found')
  const payment = await db.payment.findUnique({ where: { id: paymentId } })
  if (!payment) throw notFound('payment not found')
  try {
    const { lease, role } = await resolveLeaseAccess(db, userId, payment.leaseId)
    return { payment, lease, role }
  } catch {
    throw notFound('payment not found')
  }
}
import type { Db } from './db'

export type Portal = 'manager' | 'staff' | 'tenant' | 'none'

export interface ViewerTenant {
  id: string
  orgId: string
  fullName: string
  email: string
  phone: string | null
}

export interface ViewerProfile {
  userId: string
  portal: Portal
  /** Organizations where the user is staff or manager (from memberships; never from user_metadata). */
  staffOrgIds: string[]
  /** Tenant rows linked to this user (tenants.user_id). */
  tenants: ViewerTenant[]
}

/**
 * Roles come from the database only: memberships for staff/managers, tenants.user_id for tenants.
 * A user with any manager membership gets the manager portal; staff otherwise; tenant when only tenant rows exist.
 */
export async function resolveViewer(db: Db, userId: string): Promise<ViewerProfile> {
  const [memberships, tenants] = await Promise.all([
    db.membership.findMany({ where: { userId }, select: { orgId: true, role: true } }),
    db.tenant.findMany({ where: { userId }, select: { id: true, orgId: true, fullName: true, email: true, phone: true } }),
  ])
  const portal: Portal = memberships.some((m) => m.role === 'manager') ? 'manager' : memberships.length > 0 ? 'staff' : tenants.length > 0 ? 'tenant' : 'none'
  return { userId, portal, staffOrgIds: memberships.map((m) => m.orgId), tenants }
}
