beforeAll(async () => {
  ctx = await setup();
  browser = await chromium.launch({ executablePath: CHROME, headless: true });
  secretNeedles.push(process.env.SUPABASE_SECRET_KEY!, process.env.GATEWAY_X_SIGNATURE_KEY!, ["postgres", "postgres@"].join(":"));
